template <typename ConnectionT>
struct ThreadLocalConnectionCache {
	CachedConnection<ConnectionT> cached_conn;
	std::weak_ptr<ConnectionPool<ConnectionT>> owner;
	bool available = false;

	ThreadLocalConnectionCache() {
	}

	~ThreadLocalConnectionCache();

	void Clear();
};

